package com.sabyeguyz.clinic.databasev2.catalog;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import com.sabyeguyz.clinic.databasev2.common.PostgresIntegrationTestSupport;
import java.util.UUID;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

/** Both schemas are disposable and generated by this test; no shared schema/history is touched. */
class DatabaseV2DurationMigrationPostgresIntegrationTest {
    String url,user,password;
    @BeforeEach void connection() {
        url="jdbc:postgresql://"+env("POSTGRES_HOST","localhost")+":"+env("POSTGRES_PORT","5432")+"/"+env("POSTGRES_DB","clinic_erp");
        user=env("POSTGRES_USER","clinic");password=env("POSTGRES_PASSWORD","local-verification-password");
        try(var connection=java.sql.DriverManager.getConnection(url,user,password)) {
            assertThat(connection.isValid(5)).isTrue();
        } catch(Exception failure) { PostgresIntegrationTestSupport.handleSetupFailure("Duration migration PostgreSQL setup failed",failure); }
    }
    static String env(String name,String fallback){return System.getenv().getOrDefault(name,fallback);}
    Flyway flyway(String schema,String target) {
        return Flyway.configure().dataSource(url,user,password).locations("classpath:db/migration_new")
                .schemas(schema).defaultSchema(schema).target(target).load();
    }
    JdbcTemplate jdbc(String schema){return new JdbcTemplate(new DriverManagerDataSource(url+"?currentSchema="+schema,user,password));}
    String newSchema(){return "fast01_duration_"+UUID.randomUUID().toString().replace("-","");}
    void removeOwned(String schema){
        if(!schema.matches("fast01_duration_[a-f0-9]{32}"))throw new IllegalArgumentException("Unexpected test schema");
        jdbc(schema).execute("drop schema "+schema+" cascade");
    }
    void seed(JdbcTemplate jdbc) {
        jdbc.execute("insert into app_user(user_id,username,password_hash,user_status,last_login_at,user_create_at) values(1,'migration_fixture','unused',true,current_timestamp,current_timestamp)");
        jdbc.execute("insert into branch(branch_id,branch_code,branch_name,address,phone,branch_status,branch_create_by) values(1,'01','Preserved','Address','020000001',true,1)");
        jdbc.execute("insert into staff(staff_id,staff_code,staff_fname,staff_lname,position,branch_id,staff_status,hire_date,staff_create_by) values(1,'MIG','Preserved','Staff','Therapist',1,true,'2026-01-01',1)");
        jdbc.execute("insert into service(service_id,service_code,service_name,service_type,service_price,service_status,service_create_by) values(1,'MIG','Preserved service','SingleVisit',100,true,1)");
        jdbc.execute("insert into patient(patient_id,hn,customer_type,title,patient_fname,patient_lname,gender,phone,branch_id,registered_by) values(1,'2601100001','Thai','นาย','Preserved','Patient','Male','0890000001',1,1)");
        jdbc.execute("insert into appointment(appointment_id,patient_id,branch_id,staff_id,service_id,appointment_status,appointment_date,appointment_time,appointment_create_by) values(1,1,1,1,1,'Confirmed','2026-10-06','09:00',1)");
        jdbc.execute("insert into appointment_status_history(appointment_id,to_status,changed_by,reason) values(1,'Confirmed',1,'Preserved historical note')");
    }
    @Test void freshV2IncludesPositiveDefaultsAndConstraints() {
        String schema=newSchema();
        try {
            assertThat(flyway(schema,"latest").migrate().migrationsExecuted).isEqualTo(6);
            JdbcTemplate jdbc=jdbc(schema);seed(jdbc);
            assertThat(jdbc.queryForObject("select default_duration_minutes from service where service_id=1",Integer.class)).isEqualTo(60);
            assertThat(jdbc.queryForObject("select duration_minutes from appointment where appointment_id=1",Integer.class)).isEqualTo(60);
            assertThatThrownBy(()->jdbc.update("update service set default_duration_minutes=0 where service_id=1")).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
            assertThatThrownBy(()->jdbc.update("update appointment set duration_minutes=-1 where appointment_id=1")).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
        } finally { removeOwned(schema); }
    }
    @Test void forwardUpgradePreservesV1RowsNoteAndAppliedHistory() {
        String schema=newSchema();
        try {
            assertThat(flyway(schema,"1").migrate().migrationsExecuted).isEqualTo(1);
            JdbcTemplate jdbc=jdbc(schema);seed(jdbc);
            seedReceiptLinkRows(jdbc);
            var patient=jdbc.queryForMap("select * from patient where patient_id=1");
            var appointment=jdbc.queryForMap("select * from appointment where appointment_id=1");
            var history=jdbc.queryForMap("select * from appointment_status_history where appointment_id=1");
            var migration=jdbc.queryForMap("select * from flyway_schema_history where version='1'");
            assertThat(flyway(schema,"3").migrate().migrationsExecuted).isEqualTo(2);
            assertThat(jdbc.queryForObject("select receipt_id from sales_transaction where transaction_id=10",Long.class)).isEqualTo(10L);
            assertThat(jdbc.queryForObject("select receipt_id from sales_transaction where transaction_id=11",Long.class)).isEqualTo(11L);
            assertThat(jdbc.queryForObject("select receipt_id from sales_transaction where transaction_id=12",Long.class)).isNull();
            var appliedV3=jdbc.queryForMap("select * from flyway_schema_history where version='3'");
            assertThat(flyway(schema,"latest").migrate().migrationsExecuted).isEqualTo(3);
            assertThat(jdbc.queryForMap("select * from patient where patient_id=1")).isEqualTo(patient);
            var upgraded=jdbc.queryForMap("select * from appointment where appointment_id=1");
            assertThat(upgraded.remove("duration_minutes")).isEqualTo(60);
            assertThat(upgraded).isEqualTo(appointment);
            assertThat(jdbc.queryForMap("select * from appointment_status_history where appointment_id=1")).isEqualTo(history);
            assertThat(jdbc.queryForMap("select * from flyway_schema_history where version='1'")).isEqualTo(migration);
            assertThat(jdbc.queryForObject("select default_duration_minutes from service where service_id=1",Integer.class)).isEqualTo(60);
            assertThat(jdbc.queryForObject("select count(*) from sales_transaction",Integer.class)).isEqualTo(4);
            assertThat(jdbc.queryForObject("select gross_amount from sales_transaction where transaction_id=10",java.math.BigDecimal.class)).isEqualByComparingTo("100.00");
            assertThat(jdbc.queryForObject("select line_discount_amount from sales_transaction where transaction_id=10",java.math.BigDecimal.class)).isEqualByComparingTo("0.00");
            // IDs match, so V4 keeps these rows REVIEW_REQUIRED; V6 must not
            // infer financial receipt totals from an unresolved association.
            assertThat(jdbc.queryForObject("select receipt_link_status from sales_transaction where transaction_id=10",String.class)).isEqualTo("REVIEW_REQUIRED");
            assertThat(jdbc.queryForObject("select gross_total from receipt where receipt_id=10",java.math.BigDecimal.class)).isEqualByComparingTo("0.00");
            assertThat(jdbc.queryForObject("select net_due from receipt where receipt_id=10",java.math.BigDecimal.class)).isEqualByComparingTo("0.00");
            assertThat(jdbc.queryForObject("select count(*) from sales_transaction where receipt_link_status='REVIEW_REQUIRED'",Integer.class)).isEqualTo(4);
            assertThat(jdbc.queryForObject("select count(*) from sales_transaction_receipt_reconciliation",Integer.class)).isEqualTo(5);
            assertThat(jdbc.queryForObject("select count(*) from sales_transaction_receipt_reconciliation where reason_code='LEGACY_ID_COINCIDENCE'",Integer.class)).isEqualTo(2);
            assertThat(jdbc.queryForObject("select candidate_receipt_id from sales_transaction_receipt_reconciliation where reason_code='CROSSED_SCOPE_ID_CANDIDATE' and transaction_id=12",Long.class)).isEqualTo(12L);
            assertThat(jdbc.queryForObject("select count(*) from sales_transaction_receipt_reconciliation where reason_code='UNMATCHED_LEGACY_TRANSACTION' and candidate_receipt_id is null",Integer.class)).isEqualTo(2);
            assertThat(jdbc.queryForObject("select source_snapshot->>'transaction_id' from sales_transaction_receipt_reconciliation where transaction_id=10",String.class)).isEqualTo("10");
            assertThat(jdbc.queryForMap("select * from flyway_schema_history where version='3'")).isEqualTo(appliedV3);
        } finally { removeOwned(schema); }
    }

    private void seedReceiptLinkRows(JdbcTemplate jdbc) {
        jdbc.execute("insert into patient(patient_id,hn,customer_type,title,patient_fname,patient_lname,gender,phone,branch_id,registered_by) values(2,'2601100002','Thai','นาย','Second','Patient','Male','0890000002',1,1)");
        jdbc.execute("insert into receipt(receipt_id,receipt_no,patient_id,branch_id,sale_date,receipt_create_by) values(10,'RE-0000010',1,1,'2026-10-06',1),(11,'RE-0000011',1,1,'2026-10-06',1),(12,'RE-0000012',2,1,'2026-10-06',1)");
        jdbc.execute("""
            insert into sales_transaction(transaction_id,patient_id,branch_id,service_id,transaction_type,quantity,unit_price,amount,transaction_date,transaction_create_by)
            values (10,1,1,1,'SingleVisit',1,100,100,'2026-10-06 09:00',1),
                   (11,1,1,1,'SingleVisit',1,200,200,'2026-10-06 10:00',1),
                   (12,1,1,1,'SingleVisit',1,300,300,'2026-10-06 11:00',1),
                   (13,1,1,1,'SingleVisit',1,400,400,'2026-10-06 12:00',1)
            """);
    }
}
